package pe.cruzroja.convocatorias.notifications.domain; import java.util.UUID; public class Notification {private final UUID id,recipientId; private final String type,message,link; private boolean read; public Notification(UUID id,UUID recipientId,String type,String message,String link){if(id==null||recipientId==null||message==null||message.isBlank())throw new IllegalArgumentException("Notificación inválida");this.id=id;this.recipientId=recipientId;this.type=type;this.message=message;this.link=link;} public void markRead(){read=true;} public boolean read(){return read;} }
